art-part2","title":"Listen for the tone","title_zh":"聽一聽聲調","description":"Start by listening. You do not have to master six tones today.","teachingPoints":["In Jyutping, the number after each syllable marks its tone.","Tone 1 is high, 2 rises, 3 is mid, 4 is low and falling, 5 rises from low, and 6 is low level.","For 你好, listen to nei5 and hou2, then copy gently. A word check is not a tone score."],"dialogue":[],"examples":[{"traditional":"你好，朋友！","jyutping":"nei5 hou2, pang4 jau5!","english":"Hello, friend!"},{"traditional":"早晨，大家！","jyutping":"zou2 san4, daai6 gaa1!","english":"Good morning, everyone!"}],"vocabularyIds":["start-module-v0","start-module-v1"],"exerciseIds":["start-part2-activity1","start-part2-activity2"]},{"id":"start-part3","title":"Make a little practice routine","title_zh":"學完再練習","description":"Listen once, say it, and keep a useful phrase.","teachingPoints":["Tap the speaker to hear a model if a Cantonese device voice is available.","Tap the microphone to record and replay your own attempt.","Save a phrase with the bookmark. Find it again in My wordbook."],"dialogue":[{"speaker":"Buddy","traditional":"我學廣東話。","jyutping":"ngo5 hok6 gwong2 dung1 waa2.","english":"I learn Cantonese."},{"speaker":"You","traditional":"我講廣東話。","jyutping":"ngo5 gong2 gwong2 dung1 waa2.","english":"I speak Cantonese."}],"examples":[{"traditional":"我學廣東話。","jyutping":"ngo5 hok6 gwong2 dung1 waa2.","english":"I learn Cantonese."},{"traditional":"我聽廣東話。","jyutping":"ngo5 teng1 gwong2 dung1 waa2.","english":"I listen to Cantonese."},{"traditional":"我講廣東話。","jyutping":"ngo5 gong2 gwong2 dung1 waa2.","english":"I speak Cantonese."}],"vocabularyIds":["start-module-v3","start-module-v4","start-module-v5"],"exerciseIds":["start-part3-activity1","start-part3-activity2","start-part3-activity3"]},{"id":"start-part4","title":"Try your first exchange","title_zh":"試吓講一句","description":"Bring a greeting into a tiny workshop conversation.","teachingPoints":["Greet a buddy with 你好.","Use 早晨 when the workshop begins in the morning.","Use 再見 when you leave."],"dialogue":[{"speaker":"Buddy","traditional":"早晨！","jyutping":"zou2 san4!","english":"Good morning!"},{"speaker":"You","traditional":"早晨！","jyutping":"zou2 san4!","english":"Good morning!"},{"speaker":"Buddy","traditional":"再見！","jyutping":"zoi3 gin3!","english":"Goodbye!"},{"speaker":"You","traditional":"再見！","jyutping":"zoi3 gin3!","english":"Goodbye!"}],"examples":[{"traditional":"你好，朋友！","jyutping":"nei5 hou2, pang4 jau5!","english":"Hello, friend!"},{"traditional":"早晨，大家！","jyutping":"zou2 san4, daai6 gaa1!","english":"Good morning, everyone!"},{"traditional":"再見，聽日見！","jyutping":"zoi3 gin3, ting1 jat6 gin3!","english":"Goodbye, see you tomorrow!"}],"vocabularyIds":["start-module-v0","start-module-v1","start-module-v2"],"exerciseIds":["start-part4-activity1","start-part4-activity2","start-part4-activity3","start-part4-activity4"]}],"reference":{"title":"EduHK Survival Cantonese · topic reference","url":"https://www.eduhk.hk/cle/resources/cep/cantonese-survival-package/index.html","adaptation":"original"}},"vocabulary":[{"id":"start-module-v0","traditional":"你好","jyutping":"nei5 hou2","english":"Hello","example":"你好，朋友！","exampleJyutping":"nei5 hou2, pang4 jau5!","exampleEnglish":"Hello, friend!"},{"id":"start-module-v1","traditional":"早晨","jyutping":"zou2 san4","english":"Good morning","example":"早晨，大家！","exampleJyutping":"zou2 san4, daai6 gaa1!","exampleEnglish":"Good morning, everyone!"},{"id":"start-module-v2","traditional":"再見","jyutping":"zoi3 gin3","english":"Goodbye","example":"再見，聽日見！","exampleJyutping":"zoi3 gin3, ting1 jat6 gin3!","exampleEnglish":"Goodbye, see you tomorrow!"},{"id":"start-module-v3","traditional":"廣東話","jyutping":"gwong2 dung1 waa2","english":"Cantonese","example":"我學廣東話。","exampleJyutping":"ngo5 hok6 gwong2 dung1 waa2.","exampleEnglish":"I learn Cantonese."},{"id":"start-module-v4","traditional":"聽","jyutping":"teng1","english":"Listen","example":"我聽廣東話。","e