INSERT INTO public.lessons(id,created_by,status,version,payload) VALUES('greetings',NULL,'published',2,'{"id":"greetings","title":"Greetings through a workshop day","title_zh":"打招呼","description":"Follow one workshop day from arriving to leaving. Learn what to say, listen to a complete exchange, and respond to a new friend in context.","level":"beginner","estimated_minutes":15,"icon":"👋","topic":"Greetings","workshop":"Cantonese survival workshop · original adaptation","availability":"available","learningObjectives":["Choose a greeting for the time and situation.","Understand and respond to a short greeting exchange.","Close a conversation naturally with goodbye."],"module":{"unit":2,"introduction":"Follow one workshop day from arriving to leaving. Learn what to say, listen to a complete exchange, and respond to a new friend in context.","situation":"At the Saturday workshop, you greet a volunteer, meet a new buddy, and say goodbye when practice ends.","sections":[{"id":"greetings-part1","title":"Arrive at the workshop","title_zh":"返到工作坊","description":"Choose a greeting before you sit down.","teachingPoints":["早晨 is for the morning.","你好 can greet one person at other times too.","大家好 addresses the group."],"dialogue":[{"speaker":"Volunteer","traditional":"早晨，大家！","jyutping":"zou2 san4, daai6 gaa1!","english":"Good morning, everyone!"},{"speaker":"You","traditional":"早晨！","jyutping":"zou2 san4!","english":"Good morning!"},{"speaker":"Buddy","traditional":"你好！","jyutping":"nei5 hou2!","english":"Hello!"},{"speaker":"You","traditional":"你好！","jyutping":"nei5 hou2!","english":"Hello!"}],"examples":[{"traditional":"早晨，大家！","jyutping":"zou2 san4, daai6 gaa1!","english":"Good morning, everyone!"},{"traditional":"你好，朋友！","jyutping":"nei5 hou2, pang4 jau5!","english":"Hello, friend!"},{"traditional":"大家好！","jyutping":"daai6 gaa1 hou2!","english":"Hello, everyone!"}],"vocabularyIds":["greetings-module-v0","greetings-module-v1","greetings-module-v2"],"exerciseIds":["greetings-part1-activity1","greetings-part1-activity2","greetings-part1-activity3"]},{"id":"greetings-part2","title":"A familiar face","title_zh":"見到老朋友","description":"Listen to a short exchange between buddies.","teachingPoints":["好耐冇見 is for someone you have not seen for a while.","你最近點呀？ asks how they have been.","幾好 is a short, friendly reply."],"dialogue":[{"speaker":"Buddy","traditional":"好耐冇見！","jyutping":"hou2 noi6 mou5 gin3!","english":"Long time no see!"},{"speaker":"You","traditional":"你好！","jyutping":"nei5 hou2!","english":"Hello!"},{"speaker":"Buddy","traditional":"你最近點呀？","jyutping":"nei5 zeoi3 gan6 dim2 aa3","english":"How have you been recently?"},{"speaker":"You","traditional":"幾好，唔該。","jyutping":"gei2 hou2, m4 goi1.","english":"Pretty good, thanks."}],"examples":[{"traditional":"好耐冇見！","jyutping":"hou2 noi6 mou5 gin3!","english":"Long time no see!"},{"traditional":"你最近點呀？","jyutping":"nei5 zeoi3 gan6 dim2 aa3","english":"How have you been recently?"},{"traditional":"幾好，唔該。","jyutping":"gei2 hou2, m4 goi1.","english":"Pretty good, thanks."}],"vocabularyIds":["greetings-module-v3","greetings-module-v4","greetings-module-v5"],"exerciseIds":["greetings-part2-activity1","greetings-part2-activity2","greetings-part2-activity3"]},{"id":"greetings-part3","title":"End the workshop","title_zh":"學完講再見","description":"Finish the same conversation naturally.","teachingPoints":["再見 means goodbye.","聽日見 means see you tomorrow. Only use it when you expect to meet tomorrow.","再見，聽日見！ combines both ideas."],"dialogue":[{"speaker":"Buddy","traditional":"再見！","jyutping":"zoi3 gin3!","english":"Goodbye!"},{"speaker":"You","traditional":"再見，聽日見！","jyutping":"zoi3 gin3, ting1 jat6 gin3!","english":"Goodbye, see you tomorrow!"}],"examples":[{"traditional":"再見，朋友！","jyutping":"zoi3 gin3, pang4 jau5!","english":"Goodbye, friend!"},{"traditional":"再見，聽日見！","jyutping":"zoi3 gin3, ting1 jat6 gin3!","english":"Goodbye, see you tomorrow!"}],"vocabularyIds":["greetings-module-v6","greetings-module-v7"],"exerciseIds":["greetings-part3-activity1","greetings-part3-activity2","greetings-part3-activity3"]},{"id":"greetings-part4","title":"Put the exchange together","title_zh":"由打招呼到講再見","description":"Practise the complete arc of a short conversation.","teachingPoints":["Begin with a greeting.","Listen before choosing a reply.","Close with a goodbye."],"dialogue":[{"speaker":"Buddy","traditional":"你好！","jyutping":"nei5 hou2!","english":"Hello!"},{"speaker":"You","traditional":"你好！","jyutping":"nei5 hou2!","english":"Hello!"},{"speaker":"Buddy","traditional":"你最近點呀？","jyutping":"nei5 zeoi3 gan6 dim2 aa3","english":"How have you been recently?"},{"speaker":"You","traditional":"幾好。","jyutping":"gei2 hou2.","english":"Pretty good."},{"speaker":"Buddy","traditional":"再見！","jyutping":"zoi3 gin3!","english":"Goodbye!"}],"examples":[{"traditional":"早晨，大家！","jyutping":"zou2 san4, daai6 gaa1!","english":"Good morning, everyone!"},{"traditional":"你好，朋友！","jyutping":"nei5 hou2, pang4 jau5!","english":"Hello, friend!"},{"traditional":"你最近點呀？","jyutping":"nei5 zeoi3 gan6 dim2 aa3","english":"How have you been recently?"},{"traditional":"幾好，唔該。","jyutping":"gei2 hou2, m4 goi1.","english":"Pretty good, thanks."},{"traditional":"再見，朋友！","jyutping":"zoi3 gin3, pang4 jau5!","english":"Goodbye, friend!"},{"traditional":"再見，聽日見！","jyutping":"zoi3 gin3, ting1 jat6 gin3!","english":"Goodbye, see you tomorrow!"}],"vocabularyIds":["greetings-module-v0","greetings-module-v1","greetings-module-v4","greetings-module-v5","greetings-module-v6","greetings-module-v7"],"exerciseIds":["greetings-part4-activity1","greetings-part4-activity2"]}],"reference":{"title":"EduHK Survival Cantonese · topic reference","url":"https://www.eduhk.hk/cle/resources/cep/cantonese-survival-package/index.html","adaptation":"original"}},"vocabulary":[{"id":"greetings-module-v0","traditional":"早晨","jyutping":"zou2 san4","english":"Good morning","example":"早晨，大家！","exampleJyutping":"zou2 san4, daai6 gaa1!","exampleEnglish":"Good morning, everyone!"},{"id":"greetings-module-v1","traditional":"你好","jyutping":"nei5 hou2","english":"Hello","example":"你好，朋友！","exampleJyutping":"nei5 hou2, pang4 jau5!","exampleEnglish":"Hello, friend!"},{"id":"greetings-module-v2","traditional":"大家好","jyutping":"daai6 gaa1 hou2","english":"Hello, everyone","example":"大家好！","exampleJyutping":"daai6 gaa1 hou2!","exampleEnglish":"Hello, everyone!"},{"id":"greetings-module-v3","traditional":"好耐冇見","jyutping":"hou2 noi6 mou5 gin3","english":"Long time no see","example":"好耐冇見！","exampleJyutping":"hou2 noi6 mou5 gin3!","exampleEnglish":"Long time no see!"},{"id":"greetings-module-v4","traditional":"你最近點呀？","jyutping":"nei5 zeoi3 gan6 dim2 aa3","english":"How have you been recently?","example":"你最近點呀？","exampleJyutping":"nei5 zeoi3 gan6 dim2 aa3","exampleEnglish":"How have you been recently?"},{"id":"greetings-module-v5","traditional":"幾好","jyutping":"gei2 hou2","english":"Pretty good","example":"幾好，唔該。","exampleJyutping":"gei2 hou2, m4 goi1.","exampleEnglish":"Pretty good, thanks."},{"id":"greetings-module-v6","traditional":"再見","jyutping":"zoi3 gin3","english":"Goodbye","example":"再見，朋友！","exampleJyutping":"zoi3 gin3, pang4 jau5!","exampleEnglish":"Goodbye, friend!"},{"id":"greetings-module-v7","traditional":"聽日見","jyutping":"ting1 jat6 gin3","english":"See you tomorrow","example":"再見，聽日見！","exampleJyutping":"zoi3 gin3, ting1 jat6 gin3!","exampleEnglish":"Goodbye, see you tomorrow!"}],"grammar":["再見 means goodbye.","聽日見 means see you tomorrow. Only use it when you expect to meet tomorrow."],"culturalNotes":[{"title":"Language in context","body":"你好 is a useful general greeting. 早晨 fits the morning. Casual friends may ask 你最近點呀？; you can keep your reply short."}],"exercises":[{"id":"greetings-part1-activity1","type":"flashcard","instruction":"Explore greetings used on arrival","prompt":"Greetings in a workshop","jyutping":"","english":"","options":[],"answer":"","explanation":"Use the phrase from thi