SELECT id,version,payload FROM public.lessons WHERE id='introductions' AND created_by IS NULL AND version=2 AND payload='{"id":"introductions","title":"Introduce a pretend workshop character","title_zh":"自我介紹","description":"Create a pretend workshop character and introduce them through a short conversation. Connect a name, a pretend place, and an interest instead of memorizing isolated words.","level":"beginner","estimated_minutes":15,"icon":"💬","topic":"Introducing yourself","workshop":"Cantonese survival workshop · original adaptation","availability":"available","learningObjectives":["Introduce a pretend name and ask a buddy’s pretend name.","Use 我嚟自… with a pretend place.","Share an interest and understand a simple A-not-A question."],"module":{"unit":3,"introduction":"Create a pretend workshop character and introduce them through a short conversation. Connect a name, a pretend place, and an interest instead of memorizing isolated words.","situation":"You play Siu Ching, an imaginary learner from Hong Kong who likes drawing. You meet a new workshop buddy.","sections":[{"id":"introductions-part1","title":"Start with a pretend name","title_zh":"介紹角色個名","description":"Introduce Siu Ching and ask a buddy’s pretend name.","teachingPoints":["我叫 + name means my name is…","你叫咩名？ asks what someone is called.","For this activity, always use a pretend name."],"dialogue":[{"speaker":"You","traditional":"你好，我叫小晴。","jyutping":"nei5 hou2, ngo5 giu3 siu2 cing4.","english":"Hello, my name is Siu Ching."},{"speaker":"Buddy","traditional":"你好！","jyutping":"nei5 hou2!","english":"Hello!"},{"speaker":"You","traditional":"你叫咩名？","jyutping":"nei5 giu3 me1 meng2","english":"What is your name?"}],"examples":[{"traditional":"你好，我叫小晴。","jyutping":"nei5 hou2, ngo5 giu3 siu2 cing4.","english":"Hello, my name is Siu Ching."},{"traditional":"你叫咩名？","jyutping":"nei5 giu3 me1 meng2","english":"What is your name?"}],"vocabularyIds":["introductions-module-v0","introductions-module-v1"],"exerciseIds":["introductions-part1-activity1","introductions-part1-activity2","introductions-part1-activity3"]},{"id":"introductions-part2","title":"Give the character a place","title_zh":"角色嚟自邊度","description":"Use the imaginary character’s background.","teachingPoints":["我嚟自 + place means I come from…","你嚟自邊度？ asks where someone comes from.","Siu Ching’s pretend place is Hong Kong. You do not need to give your own location."],"dialogue":[{"speaker":"Buddy","traditional":"你嚟自邊度？","jyutping":"nei5 lai4 zi6 bin1 dou6","english":"Where do you come from?"},{"speaker":"You","traditional":"我嚟自香港。","jyutping":"ngo5 lai4 zi6 hoeng1 gong2.","english":"I come from Hong Kong."}],"examples":[{"traditional":"我嚟自香港。","jyutping":"ngo5 lai4 zi6 hoeng1 gong2.","english":"I come from Hong Kong."},{"traditional":"你嚟自邊度？","jyutping":"nei5 lai4 zi6 bin1 dou6","english":"Where do you come from?"}],"vocabularyIds":["introductions-module-v2","introductions-module-v3"],"exerciseIds":["introductions-part2-activity1","introductions-part2-activity2","introductions-part2-activity3"]},{"id":"introductions-part3","title":"Share an interest","title_zh":"講吓角色嘅興趣","description":"Use one interest and a simple yes/no pattern.","teachingPoints":["我鍾意 + activity means I like…","你鍾唔鍾意…？ puts a verb and its negative together to ask a yes/no question.","鍾意 is a positive reply; 唔鍾意 is a negative reply."],"dialogue":[{"speaker":"You","traditional":"我鍾意畫畫。","jyutping":"ngo5 zung1 ji3 waak6 waa2.","english":"I like drawing."},{"speaker":"Buddy","traditional":"你鍾唔鍾意畫畫？","jyutping":"nei5 zung1 m4 zung1 ji3 waak6 waa2","english":"Do you like drawing?"},{"speaker":"You","traditional":"鍾意。","jyutping":"zung1 ji3.","english":"Yes, I like it."}],"examples":[{"traditional":"我鍾意畫畫。","jyutping":"ngo5 zung1 ji3 waak6 waa2.","english":"I like drawing."},{"traditional":"你鍾唔鍾意畫畫？","jyutping":"nei5 zung1 m4 zung1 ji3 waak6 waa2","english":"Do you like drawing?"},{"traditional":"鍾意，我鍾意畫畫。","jyutping":"zung1 ji3, ngo5 zung1 ji3 waak6 waa2.","english":"Yes, I like drawing."},{"traditional":"唔鍾意。","jyutping":"m4 zung1 ji3.","english":"I do not like it."}],"vocabularyIds":["introductions-module-v4","introductions-module-v5","introductions-module-v6","introductions-module-v7"],"exerciseIds":["introductions-part3-activity1","introductions-part3-activity2","introductions-part3-activity3"]},{"id":"introductions-part4","title":"Introduce the whole character","title_zh":"完整介紹角色","description":"Bring the name, pretend place, and interest together.","teachingPoints":["Start with the character’s name.","Answer one question at a time.","Add one interest to make the exchange feel natural."],"dialogue":[{"speaker":"You","traditional":"我叫小晴。","jyutping":"ngo5 giu3 siu2 cing4.","english":"My name is Siu Ching."},{"speaker":"You","traditional":"我嚟自香港。","jyutping":"ngo5 lai4 zi6 hoeng1 gong2.","english":"I come from Hong Kong."},{"speaker":"You","traditional":"我鍾意畫畫。","jyutping":"ngo5 zung1 ji3 waak6 waa2.","english":"I like drawing."}],"examples":[{"traditional":"你好，我叫小晴。","jyutping":"nei5 hou2, ngo5 giu3 siu2 cing4.","english":"Hello, my name is Siu Ching."},{"traditional":"你叫咩名？","jyutping":"nei5 giu3 me1 meng2","english":"What is your name?"},{"traditional":"我嚟自香港。","jyutping":"ngo5 lai4 zi6 hoeng1 gong2.","english":"I come from Hong Kong."},{"traditional":"我鍾意畫畫。","jyutping":"ngo5 zung1 ji3 waak6 waa2.","english":"I like drawing."},{"traditional":"你鍾唔鍾意畫畫？","jyutping":"nei5 zung1 m4 zung1 ji3 waak6 waa2","english":"Do you like drawing?"},{"traditional":"鍾意，我鍾意畫畫。","jyutping":"zung1 ji3, ngo5 zung1 ji3 waak6 waa2.","english":"Yes, I like drawing."}],"vocabularyIds":["introductions-module-v0","introductions-module-v1","introductions-module-v2","introductions-module-v4","introductions-module-v5","introductions-module-v6"],"exerciseIds":["introductions-part4-activity1","introductions-part4-activity2"]}],"reference":{"title":"EduHK Survival Cantonese · topic reference","url":"https://www.eduhk.hk/cle/resources/cep/cantonese-survival-package/index.html","adaptation":"original"}},"vocabulary":[{"id":"introductions-module-v0","traditional":"我叫小晴","jyutping":"ngo5 giu3 siu2 cing4","english":"My name is Siu Ching","example":"你好，我叫小晴。","exampleJyutping":"nei5 hou2, ngo5 giu3 siu2 cing4.","exampleEnglish":"Hello, my name is Siu Ching."},{"id":"introductions-module-v1","traditional":"你叫咩名？","jyutping":"nei5 giu3 me1 meng2","english":"What is your name?","example":"你叫咩名？","exampleJyutping":"nei5 giu3 me1 meng2","exampleEnglish":"What is your name?"},{"id":"introductions-module-v2","traditional":"我嚟自香港","jyutping":"ngo5 lai4 zi6 hoeng1 gong2","english":"I come from Hong Kong","example":"我嚟自香港。","exampleJyutping":"ngo5 lai4 zi6 hoeng1 gong2.","exampleEnglish":"I come from Hong Kong."},{"id":"introductions-module-v3","traditional":"你嚟自邊度？","jyutping":"nei5 lai4 zi6 bin1 dou6","english":"Where do you come from?","example":"你嚟自邊度？","exampleJyutping":"nei5 lai4 zi6 bin1 dou6","exampleEnglish":"Where do you come from?"},{"id":"introductions-module-v4","traditional":"我鍾意畫畫","jyutping":"ngo5 zung1 ji3 waak6 waa2","english":"I like drawing","example":"我鍾意畫畫。","exampleJyutping":"ngo5 zung1 ji3 waak6 waa2.","exampleEnglish":"I like drawing."},{"id":"introductions-module-v5","traditional":"你鍾唔鍾意畫畫？","jyutping":"nei5 zung1 m4 zung1 ji3 waak6 waa2","english":"Do you like drawing?","example":"你鍾唔鍾意畫畫？","exampleJyutping":"nei5 zung1 m4 zung1 ji3 waak6 waa2","exampleEnglish":"Do you like drawing?"},{"id":"introductions-module-v6","traditional":"鍾意","jyutping":"zung1 ji3","english":"Like / yes, I like it","example":"鍾意，我鍾意畫畫。","exampleJyutping":"zung1 ji3, ngo5 zung1 ji3 waak6 waa2.","exampleEnglish":"Yes, I like drawing."},{"id":"introductions-module-v7","traditional":"唔鍾意","jyutping":"m4 zung1 ji3","english":"Do not like","example":"唔鍾意。","exampleJyutping":"m4 zung1 ji3.","exampleEnglish":"I do not like it."}],"grammar":["我叫 + name means my name is…","我嚟自 + place means I come from…","我鍾意 + activity means I like…"],"culturalNotes":[{"title":"Language in context","body":"Roleplay uses an imaginary character. Do not share your real name, home address, school, or contact details. The pretend place here is part of the character, not a request for your personal location."}],"exercises":[{"id":"introductions-part1-activity1","type":"flashcard","instruction":"Explore the name exchange","prompt":"Introduce a pretend character","jyutping":"","english":"","options":[],"answer":"","explanation":"Use the phrase from this module’s conversation.","difficulty":1,"tags":["我叫小晴"]},{"id":"introductions-part1-activity2","type":"listen_choose","instruction":"Listen to the character introduction","prompt":"我叫小晴","jyutping":"ngo5 giu3 siu2 cing4","english":"","options":["My name is Siu Ching","I like drawing","Goodbye"],"answer":"My name is Siu Ching","explanation":"我叫 introduces a name.","difficulty":1,"tags":["我叫小晴"]},{"id":"introductions-part1-activity3","type":"sentence_order","instruction":"Introduce Siu Ching","prompt":"My name is Siu Ching.","jyutping":"ngo5 giu3 siu2 cing4","english":"","options":[],"answer":"我叫小晴","explanation":"我 (I), 叫 (am called), 小晴 (the pretend name).","difficulty":1,"tags":["我叫小晴"],"tokens":["我","叫","小晴"]},{"id":"introductions-part2-activity1","type":"conversation_choice","instruction":"Answer for the imaginary character","prompt":"Buddy: 你嚟自邊度？","jyutping":"","english":"","options":["我嚟自香港。","我鍾意畫畫。","再見。"],"answer":"我嚟自香港。","explanation":"This answer supplies Siu Ching’s pretend place.","difficulty":1,"tags":["我嚟自香港"]},{"id":"introductions-part2-activity2","type":"fill_blank","instruction":"Finish the character’s introduction","prompt":"我嚟自 ___ 。","jyutping":"","english":"","options":["香港","畫畫","小晴"],"answer":"香港","explanation":"香港 is the place in our imaginary character’s background.","difficulty":1,"tags":["我嚟自香港"]},{"id":"introductions-part2-activity3","type":"scenario","instruction":"Ask about the character’s place","prompt":"Your pretend buddy has said their name. Now ask where their character comes from.","jyutping":"","english":"","options":["你嚟自邊度？","你叫咩名？","早晨！"],"answer":"你嚟自邊度？","explanation":"邊度 means where.","difficulty":1,"tags":["你嚟自邊度？"]},{"id":"introductions-part3-activity1","type":"match","instruction":"Connect the interest phrases","prompt":"Match the whole meaning","jyutping":"","english":"","options":[],"answer":"","explanation":"Use the phrase from this module’s conversation.","difficulty":1,"tags":["我鍾意畫畫","鍾意","唔鍾意"],"pairs":[{"left":"我鍾意畫畫","right":"I like drawing"},{"left":"鍾意","right":"Like / yes"},{"left":"唔鍾意","right":"Do not like"}]},{"id":"introductions-part3-activity2","type":"conversation_choice","instruction":"Answer about Siu Ching’s interest","prompt":"Siu Ching likes drawing. Buddy: 你鍾唔鍾意畫畫？","jyutping":"","english":"","options":["鍾意。","唔鍾意。","我嚟自香港。"],"answer":"鍾意。","explanation":"Use 鍾意 for this character’s positive reply.","difficulty":1,"tags":["鍾意"]},{"id":"introductions-part3-activity3","type":"speak","instruction":"Say the character’s interest","prompt":"我鍾意畫畫","jyutping":"ngo5 zung1 ji3 waak6 waa2","english":"I like drawing","options":[],"answer":"我鍾意畫畫","explanation":"Use the phrase from this module’s conversation.","difficulty":1,"tags":["我鍾意畫畫"]},{"id":"introductions-part4-activity1","type":"ai_roleplay","instruction":"Meet a new workshop character","prompt":"Use the pretend name Siu Ching and the background in this module.","jyutping":"","english":"","options":[],"answer":"","explanation":"Use the phrase from this module’s conversation.","difficulty":1,"tags":["我叫小晴"]},{"id":"introductions-part4-activity2","type":"multiple_choice","instruction":"Check the introduction pattern","prompt":"Which phrase introduces a name?","jyutping":"","english":"","options":["我叫小晴","我鍾意畫畫","我嚟自香港"],"answer":"我叫小晴","explanation":"我叫 introduces a name; the other phrases share an interest and a place.","difficulty":1,"tags":["我叫小晴"]}],"roleplay":{"scenario":"You play Siu Ching, an imaginary learner from Hong Kong who likes drawing. You meet a new workshop buddy.","studentRole":"Imaginary character Siu Ching from Hong Kong","aiRole":"Friendly workshop buddy","allowedVocabulary":["我叫小晴","你叫咩名？","我嚟自香港","你嚟自邊度？","我鍾意畫畫","你鍾唔鍾意畫畫？","鍾意","唔鍾意"],"goal":"Introduce the pretend character Siu Ching, mention Hong Kong, and talk about drawing."},"status":"published","version":2,"origin":"human","createdBy":"system","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-10-06T00:00:00Z"}'::jsonb
