INSERT INTO public.lessons(id,created_by,status,version,payload) VALUES('manners',NULL,'published',2,'{"id":"manners","title":"Kindness in everyday workshop situations","title_zh":"有禮貌","description":"Follow everyday situations at a community centre. Learn how to ask for help, thank someone, respond to a gift, and apologize after a small accident.","level":"beginner","estimated_minutes":15,"icon":"🌼","topic":"Manners","workshop":"Cantonese survival workshop · original adaptation","availability":"available","learningObjectives":["Use 唔該 for help or service and 多謝 for a gift.","Apologize with 對唔住 in the right situation.","Choose and speak a polite response within a short exchange."],"module":{"unit":4,"introduction":"Follow everyday situations at a community centre. Learn how to ask for help, thank someone, respond to a gift, and apologize after a small accident.","situation":"At your workshop you need a hand with an activity, receive a small gift, and accidentally bump into another learner.","sections":[{"id":"manners-part1","title":"Ask for a hand","title_zh":"有需要就有禮貌咁問","description":"Use a short request when an activity is difficult.","teachingPoints":["唔該 can politely get someone’s attention.","幫我 means help me.","唔該幫我 is a polite, complete request."],"dialogue":[{"speaker":"You","traditional":"唔該幫我。","jyutping":"m4 goi1 bong1 ngo5.","english":"Please help me."},{"speaker":"Buddy","traditional":"唔使客氣。","jyutping":"m4 sai2 haak3 hei3.","english":"You are welcome."},{"speaker":"You","traditional":"唔該。","jyutping":"m4 goi1.","english":"Thank you for helping."}],"examples":[{"traditional":"唔該，幫我。","jyutping":"m4 goi1, bong1 ngo5.","english":"Please help me."},{"traditional":"唔該幫我。","jyutping":"m4 goi1 bong1 ngo5.","english":"Please help me."},{"traditional":"唔使客氣。","jyutping":"m4 sai2 haak3 hei3.","english":"You are welcome."}],"vocabularyIds":["manners-module-v0","manners-module-v1","manners-module-v2"],"exerciseIds":["manners-part1-activity1","manners-part1-activity2","manners-part1-activity3"]},{"id":"manners-part2","title":"Thank someone in context","title_zh":"分清唔該同多謝","description":"Choose your thanks based on what the person did.","teachingPoints":["Use 唔該 when someone helps you or provides a service.","Use 多謝 for a gift or compliment.","多謝你 makes the thanks directly address the person."],"dialogue":[{"speaker":"Buddy","traditional":"你好！","jyutping":"nei5 hou2!","english":"Hello!"},{"speaker":"You","traditional":"多謝你！","jyutping":"do1 ze6 nei5!","english":"Thank you for the gift!"},{"speaker":"Buddy","traditional":"唔使客氣。","jyutping":"m4 sai2 haak3 hei3.","english":"You are welcome."}],"examples":[{"traditional":"唔該，幫我。","jyutping":"m4 goi1, bong1 ngo5.","english":"Please help me."},{"traditional":"多謝你！","jyutping":"do1 ze6 nei5!","english":"Thank you!"},{"traditional":"多謝你！","jyutping":"do1 ze6 nei5!","english":"Thank you!"}],"vocabularyIds":["manners-module-v0","manners-module-v3","manners-module-v4"],"exerciseIds":["manners-part2-activity1","manners-part2-activity2","manners-part2-activity3"]},{"id":"manners-part3","title":"Apologize and respond","title_zh":"講對唔住同唔緊要","description":"Practise a small accident and a kind response.","teachingPoints":["對唔住 apologizes after a mistake or bump.","唔緊要 can reassure someone: it is okay.","唔使客氣 responds to thanks, rather than replacing an apology."],"dialogue":[{"speaker":"You","traditional":"對唔住！","jyutping":"deoi3 m4 zyu6!","english":"Sorry!"},{"speaker":"Buddy","traditional":"唔緊要。","jyutping":"m4 gan2 jiu3.","english":"It is okay."}],"examples":[{"traditional":"唔使客氣。","jyutping":"m4 sai2 haak3 hei3.","english":"You are welcome."},{"traditional":"對唔住！","jyutping":"deoi3 m4 zyu6!","english":"Sorry!"},{"traditional":"唔緊要。","jyutping":"m4 gan2 jiu3.","english":"It is okay."}],"vocabularyIds":["manners-module-v2","manners-module-v5","manners-module-v6"],"exerciseIds":["manners-part3-activity1","manners-part3-activity2","manners-part3-activity3"]},{"id":"manners-part4","title":"A kind workshop day","title_zh":"喺工作坊用得出","description":"Choose a phrase for each changing situation.","teachingPoints":["Ask for help politely.","Use the type of thanks that fits the situation.","Apologize if you bump into someone."],"dialogue":[{"speaker":"You","traditional":"唔該幫我。","jyutping":"m4 goi1 bong1 ngo5.","english":"Please help me."},{"speaker":"Buddy","traditional":"唔使客氣。","jyutping":"m4 sai2 haak3 hei3.","english":"You are welcome."},{"speaker":"You","traditional":"對唔住！","jyutping":"deoi3 m4 zyu6!","english":"Sorry!"},{"speaker":"Buddy","traditional":"唔緊要。","jyutping":"m4 gan2 jiu3.","english":"It is okay."}],"examples":[{"traditional":"唔該，幫我。","jyutping":"m4 goi1, bong1 ngo5.","english":"Please help me."},{"traditional":"唔該幫我。","jyutping":"m4 goi1 bong1 ngo5.","english":"Please help me."},{"traditional":"唔使客氣。","jyutping":"m4 sai2 haak3 hei3.","english":"You are welcome."},{"traditional":"多謝你！","jyutping":"do1 ze6 nei5!","english":"Thank you!"},{"traditional":"對唔住！","jyutping":"deoi3 m4 zyu6!","english":"Sorry!"},{"traditional":"唔緊要。","jyutping":"m4 gan2 jiu3.","english":"It is okay."}],"vocabularyIds":["manners-module-v0","manners-module-v1","manners-module-v2","manners-module-v3","manners-module-v5","manners-module-v6"],"exerciseIds":["manners-part4-activity1","manners-part4-activity2"]}],"reference":{"title":"EduHK Survival Cantonese · topic reference","url":"https://www.eduhk.hk/cle/resources/cep/cantonese-survival-package/index.html","adaptation":"original"}},"vocabulary":[{"id":"manners-module-v0","traditional":"唔該","jyutping":"m4 goi1","english":"Please / thank you for help or service","example":"唔該，幫我。","exampleJyutping":"m4 goi1, bong1 ngo5.","exampleEnglish":"Please help me."},{"id":"manners-module-v1","traditional":"唔該幫我","jyutping":"m4 goi1 bong1 ngo5","english":"Please help me","example":"唔該幫我。","exampleJyutping":"m4 goi1 bong1 ngo5.","exampleEnglish":"Please help me."},{"id":"manners-module-v2","traditional":"唔使客氣","jyutping":"m4 sai2 haak3 hei3","english":"You are welcome","example":"唔使客氣。","exampleJyutping":"m4 sai2 haak3 hei3.","exampleEnglish":"You are welcome."},{"id":"manners-module-v3","traditional":"多謝","jyutping":"do1 ze6","english":"Thank you for a gift or compliment","example":"多謝你！","exampleJyutping":"do1 ze6 nei5!","exampleEnglish":"Thank you!"},{"id":"manners-module-v4","traditional":"多謝你","jyutping":"do1 ze6 nei5","english":"Thank you","example":"多謝你！","exampleJyutping":"do1 ze6 nei5!","exampleEnglish":"Thank you!"},{"id":"manners-module-v5","traditional":"對唔住","jyutping":"deoi3 m4 zyu6","english":"Sorry","example":"對唔住！","exampleJyutping":"deoi3 m4 zyu6!","exampleEnglish":"Sorry!"},{"id":"manners-module-v6","traditional":"唔緊要","jyutping":"m4 gan2 jiu3","english":"It is okay","example":"唔緊要。","exampleJyutping":"m4 gan2 jiu3.","exampleEnglish":"It is okay."}],"grammar":["幫我 means help me."],"culturalNotes":[{"title":"Language in context","body":"唔該 commonly thanks a person for help or a service and can politely get their attention. 多謝 commonly thanks someone for a gift or compliment. Context matters more than translating both as “thank you”."}],"exercises":[{"id":"manners-part1-activity1","type":"flashcard","instruction":"Explore phrases from a help exchange","prompt":"Use kindness in a complete exchange","jyutping":"","english":"","options":[],"answer":"","explanation":"Use the phrase from this module’s conversation.","difficulty":1,"tags":["唔該"]},{"id":"manners-part1-activity2","type":"listen_choose","instruction":"Listen to the request","prompt":"唔該幫我","jyutping":"m4 goi1 bong1 ngo5","english":"","options":["Please help me","Sorry","Goodbye"],"answer":"Please help me","explanation":"唔該 makes the request polite; 幫我 asks for help.","difficulty":1,"tags":["唔該幫我"]},{"id":"manners-part1-activity3","type":"sentence_order","instruction":"Build a polite request","prompt":"Please help me.","jyutping":"m4 goi1 bong1 ngo5","english":"","options":[],"answer":"唔該幫我","explanation":"The polite opener comes before the request.","difficulty":1,"tags":["唔該幫我"],"tokens":["唔該","幫","我"]},{"id":"manners-part2-activity1","type":"scenario","instruction":"A volunteer helps you","prompt":"A volunteer opens a box for your activity. How do you thank them for that help?","jyutping":"","english":"","options":["唔該。","對唔住。","再見。"],"answer":"唔該。","explanation":"Use 唔該 for help or a service.","difficulty":1,"tags":["唔該"]},{"id":"manners-part2-activity2","type":"scenario","instruction":"A buddy gives you a small gift","prompt":"Your buddy gives you a handmade bookmark. What fits?","jyutping":"","english":"","options":["多謝！","對唔住！","早晨！"],"answer":"多謝！","explanation":"Use 多謝 for a gift.","difficulty":1,"tags":["多謝"]},{"id":"manners-part2-activity3","type":"fill_blank","instruction":"Finish your thanks for the gift","prompt":"___ 你！","jyutping":"","english":"","options":["多謝","再見","早晨"],"answer":"多謝","explanation":"多謝你 means thank you.","difficulty":1,"tags":["多謝你"]},{"id":"manners-part3-activity1","type":"match","instruction":"Match polite phrases with their purpose","prompt":"Understand their real-life jobs","jyutping":"","english":"","options":[],"answer":"","explanation":"Use the phrase from this module’s conversation.","difficulty":1,"tags":["對唔住","唔緊要","唔使客氣"],"pairs":[{"left":"對唔住","right":"Apologize"},{"left":"唔緊要","right":"Reassure after a small accident"},{"left":"唔使客氣","right":"Respond to thanks"}]},{"id":"manners-part3-activity2","type":"conversation_choice","instruction":"Respond kindly to an apology","prompt":"Buddy: 對唔住！ It was only a small accidental bump.","jyutping":"","english":"","options":["唔緊要。","多謝你。","早晨。"],"answer":"唔緊要。","explanation":"唔緊要 reassures the person that the small accident is okay.","difficulty":1,"tags":["唔緊要"]},{"id":"manners-part3-activity3","type":"speak","instruction":"Practise saying sorry clearly","prompt":"對唔住","jyutping":"deoi3 m4 zyu6","english":"Sorry","options":[],"answer":"對唔住","explanation":"Use the phrase from this module’s convers